public abstract class AbstractWindowTownHall
extends AbstractBuildingMainWindow<ITownHallView> {
    public static final int RED = Color.getByName((String)"red", (int)0);
    public static final int DARKGREEN = Color.getByName((String)"darkgreen", (int)0);
    public static final int ORANGE = Color.getByName((String)"orange", (int)0);
    public static final int YELLOW = Color.getByName((String)"yellow", (int)0);

    public AbstractWindowTownHall(BuildingTownHall.View townHall, String page) {
        super(townHall, new ResourceLocation("minecolonies", "gui/townhall/").m_266382_(page));
        this.registerButton("actions", () -> new WindowMainPage(townHall).open());
        this.registerButton("infopage", () -> new WindowInfoPage(townHall).open());
        this.registerButton("permissions", () -> new WindowPermissionsPage(townHall).open());
        this.registerButton("citizens", () -> new WindowCitizenPage(townHall).open());
        this.registerButton("happiness", () -> new WindowStatsPage(townHall).open());
        this.registerButton("settings", () -> new WindowSettings(townHall).open());
        this.registerButton("alliances", () -> new WindowAlliancePage(townHall).open());
        ((Image)this.findPaneOfTypeByID(this.getWindowId() + "0", Image.class)).hide();
        ((ButtonImage)this.findPaneOfTypeByID(this.getWindowId(), ButtonImage.class)).hide();
        ((ButtonImage)this.findPaneOfTypeByID(this.getWindowId() + "1", ButtonImage.class)).show();
    }

    protected abstract String getWindowId();

    @Override
    protected boolean shouldRenderDefaultSidebar() {
        return false;
    }
}

