public WindowAlliancePage(BuildingTownHall.View building) {
    super(building, "layoutalliance.xml");
    if (building.getColony().getConnectionManager().getConnectionEvents().isEmpty() && building.getColony().getConnectionManager().getDirectlyConnectedColonies().isEmpty()) {
        this.findPaneByID("missingconnections").show();
        this.findPaneByID("activeconnections").hide();
    } else {
        this.findPaneByID("missingconnections").hide();
        this.findPaneByID("activeconnections").show();
    }
    this.directConnectionData = new ArrayList<ColonyConnection>(building.getColony().getConnectionManager().getDirectlyConnectedColonies().values());
